_EMBEDDED_TEMPLATES = [{'name': 'IIFL Portfolio', 'target': 'portfolio', 'fingerprint': ['isin name', 'holding value', 'product type'], 'match_by': 'header', 'header_aliases': {'isin': 'isin', 'scheme_name': 'isin name', 'quantity': 'qty', 'holding_value': 'holding value', 'haircut_pct': 'haircut'}, 'user_mode': 'marker'}, {'name': 'IIFL Haircut Master', 'target': 'haircut', 'fingerprint': ['scripname', 'collateralhaircut'], 'match_by': 'header', 'header_aliases': {'isin': 'isin', 'scheme_name': 'scripname', 'haircut_pct': 'collateralhaircut'}, 'user_mode': 'single'}, {'name': 'ASRENTER Allocation', 'target': 'portfolio', 'fingerprint': ['total cash available', 'gold fund name'], 'match_by': 'index', 'columns': {'scheme_name': 0, 'holding_value': 1, 'haircut_pct': 2}, 'user_mode': 'title'}]

def load_templates():
    return [dict(t) for t in _EMBEDDED_TEMPLATES]

def grids_text(grids) -> str:
    """Concatenate a sample of cell text from all grids (lower-cased)."""
    chunks = []
    for g in grids:
        sample = g.data.head(40).values.ravel().tolist()
        chunks.append(" ".join(str(x) for x in sample))
    return " ".join(chunks).lower()

def find_template(grids, target: str) -> dict | None:
    text = grids_text(grids)
    for tpl in load_templates():
        if tpl.get("target") != target:
            continue
        fp = [s.lower() for s in tpl.get("fingerprint", [])]
        if fp and all(s in text for s in fp):
            return tpl
    return None

# ===== web/sessions.py =====
"""
Analysis-Session store
======================
Replaces Streamlit's `st.session_state` for the stateless HTTP world. One
session per browser (keyed by a cookie) holds the uploaded portfolio, the
current column-mapping overrides, and the last standardized / calculated
result so `remap`, `calculate`, `user-detail` and `export` don't recompute
from scratch.

In-memory + thread-locked — correct for a single uvicorn worker (the chosen
"a few concurrent users" target). Swap this class for a Redis/DB-backed one
if the deployment ever scales to multiple workers.
"""




@dataclass
class Session:
    id: str
    created: float
    last_seen: float
    portfolio_bytes: bytes | None = None
    portfolio_name: str | None = None
    overrides: list | None = None      # parallel to plans; None per-plan = keep
    std_result: object = None          # cached StandardizeResult (portfolio)
    calc: object = None                # last CalcResult
    master_slug: str | None = None
    hc_name: str | None = None


class SessionStore:
    def __init__(self, ttl_seconds: int = 7200):
        self._d: dict[str, Session] = {}
        self._lock = threading.Lock()
        self._ttl = ttl_seconds

    def _evict_locked(self) -> None:
        now = time.time()
        dead = [k for k, s in self._d.items() if now - s.last_seen > self._ttl]
        for k in dead:
            del self._d[k]

    def create(self) -> Session:
        with self._lock:
            self._evict_locked()
            now = time.time()
            sid = uuid.uuid4().hex
            sess = Session(id=sid, created=now, last_seen=now)
            self._d[sid] = sess
            return sess

    def get(self, sid: str | None) -> Session | None:
        if not sid:
            return None
        with self._lock:
            sess = self._d.get(sid)
            if sess is not None:
                sess.last_seen = time.time()
            return sess

# ===== web/results.py =====
"""
Serialization: core result objects -> JSON-safe dicts (+ Excel export).
Keeps all pandas/numpy/NaN handling out of the route handlers.
"""





USER_MODES = ["auto", "column", "marker", "title", "single"]


# --------------------------------------------------------------------------- #
# JSON-safety helpers
# --------------------------------------------------------------------------- #

def _clean(v):
    """Scalar -> JSON-safe (NaN/NA -> None, numpy -> native)."""
    try:
        if pd.isna(v):
            return None
    except (TypeError, ValueError):
        pass
    if isinstance(v, np.integer):
        return int(v)
    if isinstance(v, np.floating):
        return float(v)
    if isinstance(v, np.bool_):
        return bool(v)
    return v


def records(df: pd.DataFrame, cols: list | None = None) -> list[dict]:
    if df is None or len(df) == 0:
        return []
    d = df[cols] if cols else df
    return [{k: _clean(v) for k, v in row.items()}
            for row in d.to_dict(orient="records")]


# --------------------------------------------------------------------------- #
# Standardize / mapping preview
# --------------------------------------------------------------------------- #

def _col_options(df: pd.DataFrame) -> list[dict]:
    opts = [{"idx": None, "label": "— none —"}]
    for c in range(df.shape[1]):
        sample = ""
        for v in df[c].tolist():
            s = "" if v is None else str(v).strip()
            if s:
                sample = s
                break
        opts.append({"idx": c, "label": f"col {c}: {sample[:32]}"})
    return opts


def _plan_to_json(plan, field_names: list[str]) -> dict:
    df = plan.grid.data
    fm = plan.fieldmap
    rep = plan.report
    return {
        "name": plan.grid.name,
        "source_kind": getattr(plan.grid, "source_kind", ""),
        "notes": list(fm.notes or []),
        "columns": {f: (int(fm.columns[f]) if fm.columns.get(f) is not None
                        else None) for f in field_names},
        "user_mode": fm.user_mode,
        "col_options": _col_options(df),
        "report": {
            "rows_kept": getattr(rep, "rows_kept", None),
            "rows_dropped": getattr(rep, "rows_dropped", None),
            "n_users": getattr(rep, "n_users", None),
            "dropped_examples": (rep.dropped_examples[:20]
                                 if getattr(rep, "dropped_examples", None) else []),
        },
        "preview": records(plan.std.head(8)) if plan.std is not None else [],
    }


def standardize_to_json(res, target: str) -> dict:
    fields = (schema.PORTFOLIO_FIELDS if target == "portfolio"
              else schema.HAIRCUT_FIELDS)
    return {
        "target": target,
        "n_rows": res.n_rows,
        "n_users": res.n_users,
        "template": res.template["name"] if res.template else None,
        "warnings": list(res.warnings or []),
        "fields": [{"name": f, "required": bool(spec.get("required"))}
                   for f, spec in fields.items()],
        "user_modes": USER_MODES,
        "plans": [_plan_to_json(p, list(fields.keys())) for p in res.plans],
    }


def norm_overrides(raw: list | None) -> list | None:
    """Normalize client override payload for pipeline.apply_overrides:
    list parallel to plans; each None (keep) or {columns:{field:int}, user_mode}."""
    if not raw:
        return None
    out = []
    for ov in raw:
        if not ov:
            out.append(None)
            continue
        cols = {f: int(c) for f, c in (ov.get("columns") or {}).items()
                if c is not None}
        um = ov.get("user_mode")
        out.append({"columns": cols, "user_mode": None if um in (None, "auto") else um})
    return out


# --------------------------------------------------------------------------- #
# Calculation -> dashboard payload
# --------------------------------------------------------------------------- #

def calc_to_json(calc, hc_df, hc_name, pf_res, dropped: int) -> dict:
    t = calc.totals
    us = calc.user_summary

    cards = {
        "n_users": t["n_users"],
        "n_holdings": t["n_holdings"],
        "portfolio_value": t["portfolio_value"],
        "haircut_value": t["haircut_value"],
        "available_margin": t["available_margin"],
        "portfolio_value_c": he.inr_compact(t["portfolio_value"]),
        "haircut_value_c": he.inr_compact(t["haircut_value"]),
        "available_margin_c": he.inr_compact(t["available_margin"]),
        "haircut_ratio": (t["haircut_value"] / t["portfolio_value"] * 100)
        if t["portfolio_value"] else None,
    }

    # charts (same definitions as the Streamlit dashboard)
    labels = ["0–10L", "10–25L", "25–50L", "50L+"]
    if len(us):
        bins = [-1, 1e6, 2.5e6, 5e6, float("inf")]
        dist = (pd.cut(us["available_margin"], bins=bins, labels=labels)
                .value_counts().reindex(labels).fillna(0))
        counts = [int(x) for x in dist.tolist()]
        tu = us.nlargest(min(20, len(us)), "available_margin")
        ti = us.nlargest(min(20, len(us)), "haircut_value")
    else:
        counts = [0, 0, 0, 0]
        tu = ti = us
    charts = {
        "margin_distribution": {"labels": labels, "counts": counts},
        "top_margin": {"users": tu["user_id"].tolist() if len(tu) else [],
                       "values": [float(x) for x in tu["available_margin"].tolist()]
                       if len(tu) else []},
        "haircut_impact": {"users": ti["user_id"].tolist() if len(ti) else [],
                           "values": [float(x) for x in ti["haircut_value"].tolist()]
                           if len(ti) else []},
    }

    validation = {
        "portfolio": [{"name": n, "ok": bool(ok), "detail": d}
                      for n, ok, d in he.validate_portfolio(pf_res.data, dropped)],
        "haircut": [{"name": n, "ok": bool(ok), "detail": d}
                    for n, ok, d in he.validate_haircut(
                        hc_df, calc.n_dup_rows, len(calc.duplicate_isin))],
        "warnings": list(pf_res.warnings or []),
    }

    flags = []
    if t["n_missing"]:
        flags.append(f"{t['n_missing']} holding(s) matched nothing")
    if t["n_scheme_matched"]:
        flags.append(f"{t['n_scheme_matched']} matched by scheme name")

    return {
        "totals": t,
        "cards": cards,
        "haircut_master": hc_name,
        "flags": flags,
        "users": records(us, ["user_id", "holdings", "portfolio_value",
                              "haircut_value", "haircut_pct", "available_margin"]),
        "charts": charts,
        "issues": {
            "scheme_matches": records(calc.scheme_matches),
            "missing": records(calc.missing_isin),
            "duplicate": records(calc.duplicate_isin),
            "n_dup_rows": calc.n_dup_rows,
        },
        "validation": validation,
    }


def user_detail_to_json(calc, user_id: str) -> dict | None:
    us = calc.user_summary
    row = us[us["user_id"] == user_id]
    if row.empty:
        return None
    u = row.iloc[0]
    dd = (calc.detail[calc.detail["user_id"] == user_id]
          .sort_values("available_margin", ascending=False))
    return {
        "user_id": user_id,
        "summary": {k: _clean(u[k]) for k in
                    ["holdings", "portfolio_value", "haircut_value",
                     "haircut_pct", "available_margin"]},
        "holdings": records(dd, ["isin", "scheme", "scrip_name", "qty",
                                 "holding_value", "haircut_pct", "haircut_amount",
                                 "available_margin", "haircut_source",
                                 "match_score"]),
    }


# --------------------------------------------------------------------------- #
# Excel export (same workbook as the Streamlit app)
# --------------------------------------------------------------------------- #

def build_excel(calc) -> bytes:
    summary = calc.user_summary.rename(columns={
        "user_id": "User ID", "holdings": "Holdings",
        "portfolio_value": "Portfolio Value", "haircut_value": "Haircut Value",
        "available_margin": "Available Margin", "haircut_pct": "Haircut %"})
    detail = calc.detail.rename(columns={
        "user_id": "User ID", "isin": "ISIN", "scheme": "Scheme",
        "scrip_name": "Matched Scrip", "qty": "Qty",
        "holding_value": "Holding Value", "haircut_pct": "Haircut %",
        "haircut_amount": "Haircut Amount", "available_margin": "Available Margin",
        "haircut_source": "Match Source", "match_score": "Match Score"})
    buf = io.BytesIO()
    with pd.ExcelWriter(buf, engine="openpyxl") as xw:
        summary.to_excel(xw, sheet_name="User Summary", index=False)
        detail.to_excel(xw, sheet_name="Detailed Holdings", index=False)
        if not calc.scheme_matches.empty:
            calc.scheme_matches.to_excel(xw, sheet_name="Scheme Matches", index=False)
        if not calc.missing_isin.empty:
            calc.missing_isin.to_excel(xw, sheet_name="Unmatched", index=False)
        if not calc.duplicate_isin.empty:
            calc.duplicate_isin.to_excel(xw, sheet_name="Duplicate ISIN", index=False)
    return buf.getvalue()

# ===== web/main.py =====
"""
Haircut Margin Calculator — FastAPI backend
===========================================
Wraps the framework-free `core` package in an HTTP API. Stateful multi-step
flow (upload → review mapping → calculate → drill-down → export) is carried by
a cookie-keyed Analysis Session (see web/sessions.py).

Run:  uvicorn web.main:app --host 0.0.0.0 --port 8000
"""





# Location-flexible: works both as web/main.py (modular) and as the flattened
# single-file build (haircut_app.py). _HERE is the dir of whichever file this is.
_HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.dirname(_HERE)
XLSX_MIME = ("application/vnd.openxmlformats-officedocument."
             "spreadsheetml.sheet")
COOKIE = "hc_sid"
TTL = int(os.environ.get("SESSION_TTL", "7200"))   # session lifetime, seconds

STORE = SessionStore(ttl_seconds=TTL)
app = FastAPI(title="Haircut Margin Calculator", version="2.0")

# Serve bundled assets only when the static dir exists (modular layout). In the
# single-file build the assets are inlined into index.html, so there is none.
_STATIC = os.path.join(_HERE, "static")
if os.path.isdir(_STATIC):
    app.mount("/static", StaticFiles(directory=_STATIC), name="static")


def _index_html_path():
    for p in (os.path.join(_HERE, "index.html"),               # single-file build
              os.path.join(_HERE, "templates", "index.html")):  # modular layout
        if os.path.exists(p):
            return p
    return None


# --------------------------------------------------------------------------- #
# Startup: seed the haircut library with the bundled IIFL master (once)
# --------------------------------------------------------------------------- #

@app.on_event("startup")
def _seed_library():
    if hs.list_masters():
        return
    try:
        raw = base64.b64decode(_IIFL_SEED_B64)
        res = pipeline.standardize(io.BytesIO(raw), "IIFL Haircut.xlsx", "haircut")
        if res.n_rows:
            hs.save_master("IIFL", raw, "IIFL Haircut.xlsx", res.data)
    except Exception as e:  # don't hide it — the console tells you why seeding failed
        print(f"[haircut] WARNING: could not seed IIFL master into '{hs._DB}': "
              f"{type(e).__name__}: {e}")


# --------------------------------------------------------------------------- #
# Session helpers
# --------------------------------------------------------------------------- #

def _get_session(request: Request, response: Response | None = None,
                 create: bool = False):
    sess = STORE.get(request.cookies.get(COOKIE))
    if sess is None and create:
        sess = STORE.create()
        if response is not None:
            response.set_cookie(COOKIE, sess.id, httponly=True,
                                samesite="lax", max_age=TTL)
    return sess


def _require_session(request: Request):
    sess = _get_session(request)
    if sess is None or sess.portfolio_bytes is None:
        raise HTTPException(400, "No portfolio uploaded in this session.")
    return sess


def _standardize_portfolio(sess):
    base = pipeline.standardize(io.BytesIO(sess.portfolio_bytes),
                                sess.portfolio_name, "portfolio")
    ovr = sess.overrides
    if ovr and len(ovr) == len(base.plans) and any(ovr):
        res = pipeline.apply_overrides(base, ovr)
    else:
        res = base
    sess.std_result = res
    return res


# --------------------------------------------------------------------------- #
# Portfolio: upload + remap
# --------------------------------------------------------------------------- #

@app.post("/api/portfolio/upload")
async def portfolio_upload(request: Request, response: Response,
                           file: UploadFile = File(...)):
    data = await file.read()
    if not data:
        raise HTTPException(400, "Empty file.")
    sess = _get_session(request, response, create=True)
    sess.portfolio_bytes = data
    sess.portfolio_name = file.filename
    sess.overrides = None
    sess.calc = None
    res = _standardize_portfolio(sess)
    return R.standardize_to_json(res, "portfolio")


class RemapBody(BaseModel):
    overrides: list


@app.post("/api/portfolio/remap")
def portfolio_remap(body: RemapBody, request: Request):
    sess = _require_session(request)
    sess.overrides = R.norm_overrides(body.overrides)
    sess.calc = None
    res = _standardize_portfolio(sess)
    return R.standardize_to_json(res, "portfolio")


# --------------------------------------------------------------------------- #
# Haircut library
# --------------------------------------------------------------------------- #

@app.get("/api/haircut-masters")
def haircut_list():
    return {"masters": hs.list_masters()}


@app.post("/api/haircut-masters/preview")
async def haircut_preview(file: UploadFile = File(...),
                          overrides: str = Form(None)):
    data = await file.read()
    if not data:
        raise HTTPException(400, "Empty file.")
    base = pipeline.standardize(io.BytesIO(data), file.filename, "haircut")
    ovr = R.norm_overrides(json.loads(overrides)) if overrides else None
    res = (pipeline.apply_overrides(base, ovr)
           if ovr and len(ovr) == len(base.plans) else base)
    return R.standardize_to_json(res, "haircut")


@app.post("/api/haircut-masters")
async def haircut_save(name: str = Form(...), file: UploadFile = File(...),
                       overrides: str = Form(None)):
    data = await file.read()
    if not name.strip():
        raise HTTPException(400, "A master name is required.")
    if not data:
        raise HTTPException(400, "Empty file.")
    base = pipeline.standardize(io.BytesIO(data), file.filename, "haircut")
    ovr = R.norm_overrides(json.loads(overrides)) if overrides else None
    res = (pipeline.apply_overrides(base, ovr)
           if ovr and len(ovr) == len(base.plans) else base)
    if res.n_rows == 0:
        raise HTTPException(422, "No haircut records detected — fix the mapping.")
    try:
        meta = hs.save_master(name, data, file.filename, res.data)
    except Exception as e:  # surface the real cause (perms / disk) to the user
        raise HTTPException(
            500, f"Could not save to the database '{hs._DB}': "
                 f"{type(e).__name__}: {e}. Check the location is writable, or set "
                 f"the HAIRCUT_DB env var to a writable path.")
    return meta


@app.delete("/api/haircut-masters/{slug}")
def haircut_delete(slug: str):
    hs.delete_master(slug)
    return {"ok": True, "deleted": slug}


# --------------------------------------------------------------------------- #
# Calculate + drill-down + export
# --------------------------------------------------------------------------- #

class CalcBody(BaseModel):
    master_slug: str
    policy: str = "zero"
    threshold: float = 88.0


@app.post("/api/calculate")
def calculate(body: CalcBody, request: Request):
    sess = _require_session(request)
    meta = hs.get_meta(body.master_slug)
    if not meta:
        raise HTTPException(404, "Selected haircut master not found.")
    pf_res = sess.std_result or _standardize_portfolio(sess)
    hc_df = hs.load_master(body.master_slug)
    calc = he.compute(pf_res.data, hc_df,
                      missing_policy=body.policy,
                      scheme_threshold=float(body.threshold))
    sess.calc = calc
    sess.master_slug = body.master_slug
    sess.hc_name = meta["name"]
    dropped = sum(p.report.rows_dropped for p in pf_res.plans)
    return R.calc_to_json(calc, hc_df, meta["name"], pf_res, dropped)


@app.get("/api/user-detail")
def user_detail(user_id: str, request: Request):
    sess = _get_session(request)
    if sess is None or sess.calc is None:
        raise HTTPException(400, "Nothing calculated in this session yet.")
    d = R.user_detail_to_json(sess.calc, user_id)
    if d is None:
        raise HTTPException(404, "Unknown user.")
    return d


@app.get("/api/export")
def export(request: Request):
    sess = _get_session(request)
    if sess is None or sess.calc is None:
        raise HTTPException(400, "Nothing calculated in this session yet.")
    data = R.build_excel(sess.calc)
    return StreamingResponse(
        io.BytesIO(data), media_type=XLSX_MIME,
        headers={"Content-Disposition":
                 "attachment; filename=haircut_margin_results.xlsx"})


@app.get("/api/health")
def health():
    return {"status": "ok", "masters": len(hs.list_masters())}


# --------------------------------------------------------------------------- #
# Root — the dashboard
# --------------------------------------------------------------------------- #

@app.get("/")
def index():
    p = _index_html_path()
    if not p:
        raise HTTPException(500, "index.html not found next to the app.")
    with open(p, encoding="utf-8") as fh:
        return HTMLResponse(fh.read())


# --- embedded IIFL haircut master (seeds the library on first run) ---
_IIFL_SEED_B64 = ""


if __name__ == "__main__":
    import uvicorn
    uvicorn.run(app, host="0.0.0.0",
                port=int(os.environ.get("PORT", "8000")))
